{
      gate.verify();
      Snapshot directory = directory();
      try {
        root.atExistingEntryHandle(name, held -> file(held, directory));
      } catch (StorageIoException missing) {
        if (missing.reason() != StorageIoException.Reason.MISSING) throw unavailable();
        require(directory.sameIdentity(directory()));
        gate.verify();
        return;
      }
      throw unavailable();
    }

{
      requireClear();
      Snapshot directory = directory();
      root.atDirectory(
          held -> {
            Path marker = held.resolve(name);
            try (FileChannel channel =
                FileChannel.open(
                    marker,
                    Set.of(
                        StandardOpenOption.CREATE_NEW,
                        StandardOpenOption.WRITE,
                        LinkOption.NOFOLLOW_LINKS),
                    PosixFilePermissions.asFileAttribute(
                        PosixFilePermissions.fromString("rw-------")))) {
              channel.force(true);
            } catch (FileAlreadyExistsException collision) {
              throw unavailable();
            }
            return true;
          });
      // Failure from here onward leaves the marker behind and forbids a start request.
      root.sync();
      Snapshot created = root.atExistingEntryHandle(name, held -> file(held, directory));
      require(directory.sameIdentity(directory()));
      gate.verify();
      begun = true;
      return new Intent(this, created);
    }

{
      require(!begun);
      gate.verify();
      var directory = directory();
      var captured = root.atExistingEntryHandle(name, p -> file(p, directory));
      require(directory.sameIdentity(directory()));
      gate.verify();
      begun = true;
      return new Intent(this, captured);
    }

{
      Objects.requireNonNull(intent, "same-start marker");
      if (!begun || intent.owner != this) throw unavailable();
      gate.verify();
      Snapshot directory = directory();
      Snapshot actual = root.atExistingEntryHandle(name, held -> file(held, directory));
      require(intent.marker.equals(actual));
      root.unlinkEntry(name);
      require(directory.sameIdentity(directory()));
      begun = false;
      requireClear();
    }

{
      Objects.requireNonNull(intent, "same publication marker");
      require(begun && intent.owner == this);
      gate.verify();
      var directory = directory();
      require(intent.marker.equals(root.atExistingEntryHandle(name, p -> file(p, directory))));
      require(directory.sameIdentity(directory()));
      gate.verify();
    }

{
      gate.verify();
      var directory = directory();
      boolean[] entered = {false};
      try {
        root.atExistingEntryHandle(
            name,
            p -> {
              entered[0] = true;
              return file(p, directory);
            });
        require(directory.sameIdentity(directory()));
        gate.verify();
      } catch (StorageIoException missing) {
        require(!entered[0] && missing.reason() == StorageIoException.Reason.MISSING);
        begin();
      }
    }

{
      root.close();
    }

{
      byte[] content = request.encode();
      try {
        Snapshot directory = directory();
        Snapshot written =
            root.createPrivatePart(
                part,
                held -> {
                  Snapshot empty = file(held, 0, directory);
                  require(empty.metadata().size() == 0);
                  write(held, content);
                  Snapshot result = file(held, 1, directory);
                  require(empty.sameIdentity(result) && result.metadata().size() == content.length);
                  verify(held, result, content);
                  return result;
                });
        require(written.equals(root.atPartHandle(part, p -> file(p, 1, directory))));
        root.publishAs(part, NAME);
        Snapshot published = root.atExistingEntryHandle(NAME, p -> file(p, 1, directory));
        require(written.samePublishedFile(published));
        root.atExistingEntryHandle(
            NAME,
            p -> {
              verify(p, published, content);
              return true;
            });
        require(published.equals(root.atExistingEntryHandle(NAME, p -> file(p, 1, directory))));
        require(directory.sameIdentity(directory()));
      } finally {
        Arrays.fill(content, (byte) 0);
      }
    }

{
      Snapshot before = directory();
      BackupWorkerRequest previous;
      try {
        previous = read();
      } catch (StorageIoException missing) {
        if (missing.reason() != StorageIoException.Reason.MISSING) throw missing;
        require(before.equals(directory()));
        prepare(expected, part);
        return;
      }
      require(expected.equals(previous) && expected.equals(read()));
      require(before.equals(directory()));
    }

{
      Snapshot before = directory();
      BackupWorkerRequest previous;
      try {
        previous = read();
      } catch (StorageIoException missing) {
        if (missing.reason() != StorageIoException.Reason.MISSING) throw missing;
        require(before.equals(directory()));
        prepare(expected, part);
        return;
      }
      if (expected.equals(previous)) {
        prepareResume(expected, part);
        return;
      }
      require(
          expected.run().equals(previous.run()) && previous.started().isBefore(expected.started()));
      proof.verify(previous);
      require(previous.equals(read()) && before.equals(directory()));
      retire(previous);
      prepare(expected, part);
    }

{
      byte[] bytes = new byte[BackupWorkerRequest.MAXIMUM_BYTES + 1];
      try {
        Snapshot directory = directory();
        Snapshot original =
            root.atExistingEntryHandle(
                NAME,
                p -> {
                  Snapshot before = file(p, 1, directory);
                  read(p, before.metadata().size(), bytes);
                  require(before.equals(file(p, 1, directory)));
                  return before;
                });
        require(original.equals(root.atExistingEntryHandle(NAME, p -> file(p, 1, directory))));
        require(directory.equals(directory()));
        return BackupWorkerRequest.consume(Arrays.copyOf(bytes, (int) original.metadata().size()));
      } finally {
        Arrays.fill(bytes, (byte) 0);
      }
    }

{
      Snapshot directory = directory();
      Snapshot before = root.atExistingEntryHandle(NAME, p -> file(p, 1, directory));
      require(expected.equals(read()));
      require(before.equals(root.atExistingEntryHandle(NAME, p -> file(p, 1, directory))));
      root.unlinkEntry(NAME);
      root.sync();
      require(directory.sameIdentity(directory()));
    }

{
      Snapshot before = directory();
      root.atDirectory(
          held -> {
            try (var names = java.nio.file.Files.newDirectoryStream(held)) {
              require(!names.iterator().hasNext());
            } catch (java.nio.file.DirectoryIteratorException failure) {
              StorageIoException.preserveFatal(failure);
              throw unavailable();
            }
            guard();
            return Boolean.TRUE;
          });
      require(before.equals(directory()));
    }

{
      Snapshot before = directory();
      root.atDirectory(
          held -> {
            var observed = new HashSet<String>();
            try (var names = java.nio.file.Files.newDirectoryStream(held)) {
              for (var entry : names) {
                var filename = entry.getFileName();
                if (filename == null) throw unavailable();
                require(observed.add(filename.toString()));
              }
            } catch (java.nio.file.DirectoryIteratorException failure) {
              StorageIoException.preserveFatal(failure);
              throw unavailable();
            }
            require(observed.equals(expected));
            guard();
            return Boolean.TRUE;
          });
      require(before.equals(directory()));
    }

{
      try {
        Snapshot directory = directory();
        Snapshot written =
            root.createPrivatePart(
                part,
                held -> {
                  Snapshot empty = file(held, 0, directory);
                  require(empty.metadata().size() == 0);
                  write(held, content);
                  Snapshot result = file(held, 1, directory);
                  require(empty.sameIdentity(result) && result.metadata().size() == content.length);
                  verify(held, result, content);
                  return result;
                });
        require(written.equals(root.atPartHandle(part, p -> file(p, 1, directory))));
        root.publishAs(part, name);
        Snapshot published = root.atExistingEntryHandle(name, p -> file(p, 1, directory));
        require(written.samePublishedFile(published));
        root.atExistingEntryHandle(
            name,
            p -> {
              verify(p, published, content);
              return true;
            });
        require(published.equals(root.atExistingEntryHandle(name, p -> file(p, 1, directory))));
        require(directory.sameIdentity(directory()));
      } finally {
        Arrays.fill(content, (byte) 0);
      }
    }

{
      byte[] bytes = new byte[maximum + 1];
      try {
        Snapshot directory = directory();
        Snapshot original =
            root.atExistingEntryHandle(
                name,
                p -> {
                  Snapshot before = file(p, 1, directory);
                  read(p, before.metadata().size(), bytes);
                  require(before.equals(file(p, 1, directory)));
                  return before;
                });
        require(original.equals(root.atExistingEntryHandle(name, p -> file(p, 1, directory))));
        require(directory.equals(directory()));
        return Arrays.copyOf(bytes, (int) original.metadata().size());
      } finally {
        Arrays.fill(bytes, (byte) 0);
      }
    }

{
      byte[] actual = new byte[0];
      try {
        Snapshot directory = directory();
        Snapshot before = root.atExistingEntryHandle(name, p -> file(p, 1, directory));
        actual = readBytes();
        require(Arrays.equals(expected, actual));
        require(before.equals(root.atExistingEntryHandle(name, p -> file(p, 1, directory))));
        root.unlinkEntry(name);
        root.sync();
        require(directory.sameIdentity(directory()));
      } finally {
        Arrays.fill(expected, (byte) 0);
        Arrays.fill(actual, (byte) 0);
      }
    }

{
      begin();
      try {
        T result;
        {
          result =
              ResourceScope.acquire(
                  () -> OwnedTransferDirectory.open(directories, varPath),
                  OwnedTransferDirectory::close,
                  var -> {
                    return ResourceScope.acquire(
                        () -> var.openExistingChild(LITERAL_LIB),
                        OwnedTransferDirectory::close,
                        lib -> {
                          return ResourceScope.acquire(
                              () -> lib.openExistingChild(LITERAL_SCHUBERT_NK),
                              OwnedTransferDirectory::close,
                              app -> {
                                return ResourceScope.acquire(
                                    () -> app.openExistingChild("maintenance"),
                                    OwnedTransferDirectory::close,
                                    maintenance -> {
                                      return ResourceScope.acquire(
                                          () -> maintenance.openExistingChild(LITERAL_RUNS),
                                          OwnedTransferDirectory::close,
                                          runs -> {
                                            return ResourceScope.acquire(
                                                () ->
                                                    maintenance.openExistingChild(LITERAL_ATTEMPTS),
                                                OwnedTransferDirectory::close,
                                                attempts -> {
                                                  var roots =
                                                      List.of(
                                                          var,
                                                          lib,
                                                          app,
                                                          maintenance,
                                                          runs,
                                                          attempts);
                                                  var session = new Session(roots, capture(roots));
                                                  try {
                                                    session.verifyNamespace();
                                                    T completed =
                                                        Objects.requireNonNull(
                                                            operation.execute(session),
                                                            "run operation result");
                                                    session.finish();
                                                    return completed;
                                                  } finally {
                                                    session.invalidate();
                                                  }
                                                });
                                          });
                                    });
                              });
                        });
                  });
        }
        require(!Thread.currentThread().isInterrupted());
        return result;
      } catch (IOException failure) {
        throw unavailable();
      }
    }

{
        require(open);
        begin();
        try {
          T value = operation.execute();
          require(!Thread.currentThread().isInterrupted());
          return value;
        } catch (IOException | GeneralSecurityException failure) {
          throw unavailable();
        }
      }

{
        try {
          begin();
          verifyNamespace();
        } finally {
          open = false;
        }
      }

{
      try {
        Snapshot before = begin();
        Optional<Epoch> old = existingCurrent(before);
        require(old.isEmpty() || !old.orElseThrow().epoch().equals(epoch));
        replaceCurrent(next, before);
        finish(before);
        return next;
      } catch (IOException failure) {
        throw unavailable();
      }
    }

{
      byte[] content = StartupPermitRecords.permit(permit);
      try {
        Snapshot before = begin();
        require(expected.state() == State.INVALID);
        require(expected.equals(current(before)));
        require(
            expected.boot().equals(permit.boot())
                && expected.epoch().equals(permit.epoch())
                && expected.activation().equals(permit.activation()));
        UUID part = parts.next();
        Snapshot original = writePart(part, content, before);
        verify(proof, IssuePhase.BEFORE_PUBLICATION, expected);
        require(expected.equals(current(before)));
        require(
            original.equals(root.atExistingEntryHandle(part + ".part", p -> file(p, 1, before))));
        checkBytes(part + ".part", content, before);
        String name = permit.epoch() + ".permit";
        root.publishAs(part, name);
        require(
            original.samePublishedFile(root.atExistingEntryHandle(name, p -> file(p, 1, before))));
        checkBytes(name, content, before);
        require(expected.equals(current(before)));
        String digest = HexFormat.of().formatHex(io.digest().digest(content));
        Epoch issued = expected.issued(digest);
        verify(proof, IssuePhase.BEFORE_ISSUED, expected);
        require(expected.equals(current(before)));
        replaceCurrent(issued, before);
        require(permit.equals(readIssuedAt(before)));
        verify(proof, IssuePhase.AFTER_READBACK, issued);
        require(issued.equals(current(before)));
        require(permit.equals(readIssuedAt(before)));
        finish(before);
        return issued;
      } catch (IOException | NoSuchAlgorithmException failure) {
        throw unavailable();
      } finally {
        Arrays.fill(content, (byte) 0);
      }
    }

{
      byte[] content = StartupPermitRecords.permit(attempted);
      try {
        Snapshot before = begin();
        require(expected.state() == State.INVALID);
        require(
            expected.boot().equals(attempted.boot())
                && expected.epoch().equals(attempted.epoch())
                && expected.activation().equals(attempted.activation()));
        Epoch actual = current(before);
        if (!actual.equals(expected)) {
          String digest = HexFormat.of().formatHex(io.digest().digest(content));
          require(actual.equals(expected.issued(digest)));
        }
        replaceCurrent(expected, before);
        require(expected.equals(current(before)));
        finish(before);
        return expected;
      } catch (IOException | NoSuchAlgorithmException failure) {
        throw unavailable();
      } finally {
        Arrays.fill(content, (byte) 0);
      }
    }

{
      try {
        Snapshot before = begin();
        Epoch result = current(before);
        finish(before);
        return result;
      } catch (IOException failure) {
        throw unavailable();
      }
    }

{
      try {
        Snapshot before = begin();
        requireNoPublicationIntent(before);
        Permit result = readIssuedAt(before);
        requireNoPublicationIntent(before);
        finish(before);
        return result;
      } catch (IOException failure) {
        throw unavailable();
      }
    }

{
      byte[] bytes = new byte[0];
      try {
        var before = begin();
        require(expected.state() == State.INVALID && expected.equals(current(before)));
        bytes = read(expected.epoch() + ".permit", before);
        var former = expected.issued(HexFormat.of().formatHex(io.digest().digest(bytes)));
        var permit = StartupPermitRecords.verifyIssued(former, bytes);
        require(expected.equals(current(before)));
        finish(before);
        return new Revoked(former, permit);
      } catch (IOException | NoSuchAlgorithmException failure) {
        throw unavailable();
      } finally {
        Arrays.fill(bytes, (byte) 0);
      }
    }

{
      try {
        var before = begin();
        require(expected.state() == State.ISSUED && current(before).equals(expected));
        require(readIssuedAt(before).equals(attempted));
        finish(before);
      } catch (IOException failure) {
        throw unavailable();
      }
    }

{
      Objects.requireNonNull(
              Objects.requireNonNull(counters.get(step), "closed batch step").get(status),
              "closed batch status")
          .increment();
      if (status == Status.SUCCESS) {
        var state = Objects.requireNonNull(lastSuccess.get(step), "closed batch success state");
        var previous = state.get();
        if (previous.isEmpty() || endedAt.isAfter(previous.orElseThrow()))
          state.set(Optional.of(endedAt));
      }
    }

{
      long now = ticks.getAsLong();
      long elapsed = now - origin;
      if (now - last < 0 || elapsed < 0)
        throw new IllegalArgumentException("invalid monitoring clock sequence");
      var at = Objects.requireNonNull(utc.instant(), "observation instant");
      var context = new ObservationContext(clearance, at, Duration.ofNanos(elapsed));
      last = now;
      return context;
    }

{
      return observeLocked(consecutive, context, action);
    }

{
      final ObservationContext context;
      try {
        context = clock.context(clearance);
      } catch (RuntimeException | Error unavailableClock) {
        interrupted = true;
        throw unavailableClock;
      }
      return observeLocked(consecutive, context, action);
    }

{
        Objects.requireNonNull(gate);
        if ((unit != MaintenanceUnit.API && unit != MaintenanceUnit.WEB)
            || retainedStatus != Status.CLIENT_EXITED_ZERO
            || !stdinClosed
            || !streamsClosed
            || retired
            || retiring
            || retireUncertain) throw new IOException("service intent proof unavailable");
        context.recheck();
        gate.verify();
        marker.requireRetained();
        gate.verify();
        context.recheck();
      }

{
        Objects.requireNonNull(before);
        Objects.requireNonNull(after);
        if ((unit != MaintenanceUnit.API
                && unit != MaintenanceUnit.WEB
                && unit != MaintenanceUnit.CADDY)
            || !stdinClosed
            || !streamsClosed) throw new IOException("live intent retirement unavailable");
        retireAfter(before);
        // Failure after unlink/close is UNKNOWN and must be retained by the enclosing parent.
        context.recheck();
        after.verify();
        context.recheck();
      }

{
        if ((unit != MaintenanceUnit.API
                && unit != MaintenanceUnit.WEB
                && unit != MaintenanceUnit.CADDY)
            || retired
            || retiring
            || retireUncertain) throw new IOException("service observation close unavailable");
        retireUncertain = true;
        marker.closeObservation();
      }

{
        Objects.requireNonNull(gate, "parent completion proof");
        if (retainedStatus != Status.CLIENT_EXITED_ZERO || retired || retiring || retireUncertain)
          throw new IOException("backup intent retirement unavailable");
        retiring = true;
        try {
          context.recheck();
          gate.verify();
          context.recheck();
          retireUncertain = true;
          marker.retire();
          retired = true;
        } finally {
          retiring = false;
        }
      }

{
        if (retainedStatus != Status.UNKNOWN || streamsClosed || poisoned) return retainedStatus;
        if (process == null) return Status.UNKNOWN;
        try {
          context.recheck();
          if (Thread.currentThread().isInterrupted()) return Status.UNKNOWN;
          if (!stdinClosed) {
            stdinClosed = true;
            Objects.requireNonNull(process.getOutputStream(), "start stdin").close();
          }
          if (budget.isPresent()) {
            long remaining = budget.orElseThrow().remainingNanos();
            if (!process.waitFor(
                Math.min(TimeUnit.SECONDS.toNanos(120), remaining), TimeUnit.NANOSECONDS))
              return Status.UNKNOWN;
            budget.orElseThrow().requireWithin();
          } else if (!process.waitFor(120, TimeUnit.SECONDS)) return Status.UNKNOWN;
          if (Thread.currentThread().isInterrupted()) return Status.UNKNOWN;
          var stdout = Objects.requireNonNull(process.getInputStream(), "start stdout");
          Closeable stderr;
          try {
            stderr = Objects.requireNonNull(process.getErrorStream(), "start stderr");
          } catch (RuntimeException | Error failure) {
            closeOne(stdout);
            throw failure;
          }
          boolean closed = closeBoth(stdout, stderr);
          streamsClosed = true;
          if (!closed) return Status.UNKNOWN;
          context.recheck();
          retainedStatus =
              process.exitValue() == 0 ? Status.CLIENT_EXITED_ZERO : Status.CLIENT_EXITED_NONZERO;
          return retainedStatus;
        } catch (InterruptedException interrupted) {
          Thread.currentThread().interrupt();
          return Status.UNKNOWN;
        } catch (IOException | RuntimeException | Error failure) {
          poisoned = true;
          return Status.UNKNOWN;
        }
      }

{
      try {
        check();
        var before = Objects.requireNonNull(observations.read(), "backup state");
        var placement = placement(observations.placement());
        if (!before.quiescent()) {
          check();
          return Optional.empty();
        }
        FixedUnitCgroupNamespace.Snapshot first = namespace();
        if (first.present()) {
          // SSC100/BUG308: a manager with no group cannot attest this present kernel tree.
          require(target.unit().controlGroup().equals(placement.get("ControlGroup")));
          var all = Objects.requireNonNull(observations.quiescent(), "whole Unit observation");
          if (all.isEmpty() || !before.matches(all.orElseThrow())) {
            check();
            return Optional.empty();
          }
        }
        require(before.matches(Objects.requireNonNull(observations.read(), "backup state")));
        require(placement.equals(placement(observations.placement())));
        // Reopen the current host path; held old ancestors alone cannot attest namespace binding.
        require(first.equals(namespace()));
        require(before.matches(Objects.requireNonNull(observations.read(), "backup state")));
        require(placement.equals(placement(observations.placement())));
        check();
        return Optional.of(before);
      } catch (IOException failure) {
        throw unavailable();
      }
    }

{
        if (retainedStatus != Status.UNKNOWN || streamsClosed || poisoned) return retainedStatus;
        if (process == null) return Status.UNKNOWN; // No handle means no reaping proof.
        try {
          context.recheck();
          if (Thread.currentThread().isInterrupted()) return Status.UNKNOWN;
          if (!stdinClosed) {
            stdinClosed = true; // A failed close is not retried against an uncertain descriptor.
            Objects.requireNonNull(process.getOutputStream(), "stop stdin").close();
          }
          if (!process.waitFor(120, TimeUnit.SECONDS)) return Status.UNKNOWN;
          if (Thread.currentThread().isInterrupted()) return Status.UNKNOWN;
          var stdout = Objects.requireNonNull(process.getInputStream(), "stop stdout");
          Closeable stderr;
          try {
            stderr = Objects.requireNonNull(process.getErrorStream(), "stop stderr");
          } catch (RuntimeException | Error failure) {
            closeOne(stdout);
            throw failure;
          }
          boolean closed = closeBoth(stdout, stderr);
          streamsClosed = true;
          if (!closed) return Status.UNKNOWN;
          context.recheck();
          retainedStatus =
              process.exitValue() == 0 ? Status.CLIENT_EXITED_ZERO : Status.CLIENT_EXITED_NONZERO;
          return retainedStatus;
        } catch (InterruptedException interrupted) {
          Thread.currentThread().interrupt();
          return Status.UNKNOWN;
        } catch (IOException | RuntimeException | Error failure) {
          poisoned = true;
          return Status.UNKNOWN;
        }
      }

{
      if (point == null
          || (point == Point.BEFORE_EXEC
              && profile.phase() != FixedNativeCoverageProfile.Phase.ROOT)
          || (point == Point.CLOSING && !profile.supportsClosing()))
        throw new IllegalArgumentException("fixed PT checkpoint point required");
      if (!attempted.add(point)) throw unavailable();
      if (point == Point.CLOSING) require(terminalCompleted);
      require(VERSION.equals(agent.version()) && profile.sessionId().equals(agent.session()));
      byte[] value = agent.executionDataWithoutReset();
      if (value == null || value.length < 5 || value.length > MAX_BYTES) throw unavailable();
      // Independent collector validates the full session/class byte stream, never this header
      // alone.
      require(
          value[0] == 1
              && value[1] == (byte) 0xc0
              && value[2] == (byte) 0xc0
              && value[3] == 0x10
              && value[4] == 7);
      require(VERSION.equals(agent.version()) && profile.sessionId().equals(agent.session()));
      String suffix =
          switch (point) {
            case BEFORE_EXEC -> ".before-exec.exec";
            case TERMINAL -> ".terminal.exec";
            case CLOSING -> ".closing.exec";
          };
      export.write(profile.invocation() + suffix, value.clone());
      if (point == Point.TERMINAL) terminalCompleted = true;
    }
